//! Frozen Python outputs are immutable evidence, never regenerated by Rust.
use crate::{digest, safe_file};
use serde::Deserialize;
use std::{collections::BTreeSet, path::Path};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GoldenSet {
    schema: u32,
    baseline: String,
    files: Vec<Golden>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Golden {
    path: String,
    sha256: String,
}

pub fn check(root: &Path) -> Result<usize, &'static str> {
    let data = safe_file(root, "fixtures/rust/frozen-goldens.json")?;
    verify(root, &data)
}
fn verify(root: &Path, data: &[u8]) -> Result<usize, &'static str> {
    let set: GoldenSet = serde_json::from_slice(data).map_err(|_| "invalid_golden_manifest")?;
    if set.schema != 1 || set.baseline != "df20719" || set.files.is_empty() {
        return Err("invalid_golden_baseline");
    }
    let mut paths = BTreeSet::new();
    for file in &set.files {
        if !file.path.starts_with("fixtures/rust/")
            || !file.path.ends_with(".json")
            || !paths.insert(&file.path)
        {
            return Err("invalid_golden_path");
        }
        let bytes = safe_file(root, &file.path)?;
        if digest(&bytes) != file.sha256 {
            return Err("golden_digest_mismatch");
        }
        serde_json::from_slice::<serde_json::Value>(&bytes).map_err(|_| "invalid_golden_json")?;
    }
    Ok(paths.len())
}
